					emitModelWarning(classified);
					return {
						output: classified,
						content: classified,
						summary: classified,
						modifiedFiles: [],
						failed: true,
						failureReason: classified,
						harnessId: runHarnessId,
						fallbackStageId: null,
						logEntries: streamer.snapshot().entries,
					};
