 * @example await executeStage(store, "p1", "t1", { stages }) => { status: "complete", … }
 ***/
export async function executeStage(
	store,
	projectId,
	taskId,
	{
		stages = [],
		projectCwd,
		execRunner,
		agentRunner,
		promptEngine,
		eventBridge: overrideBridge,
		priority = "normal",
	} = {},
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;

